<?php use App\Support\Ui; $isActive=(bool)$candidate['active']; $hasUpcoming=count($upcoming)>0; ?>
<div class="page-heading candidate-detail-heading"><div><a class="back-link" href="<?= $e($url('admin/candidates')) ?>">← Candidates</a><span class="eyebrow">CANDIDATE PROFILE</span><h1><?= $e($candidate['full_name']) ?></h1><p><?= $e($candidate['phone']) ?></p></div><div class="candidate-primary-actions"><?php if($isActive):?><a class="button primary" href="<?= $e($url('admin/interview/new?candidate_id='.$candidate['id'])) ?>"><?= Ui::icon('plus') ?>Book interview</a><?php endif;?></div></div>
<section class="card candidate-summary"><?= Ui::candidateAvatar($candidate,'soft profile-avatar') ?><div><div class="candidate-name-line"><h2><?= $e($candidate['full_name']) ?></h2><span class="badge <?= $isActive?'green':'neutral' ?>"><?= $isActive?'Active':'Inactive' ?></span></div><span class="candidate-stack-label">Tech Stack</span><?php if($candidate['tech_stack']):?><span class="skill-chips"><?php foreach($candidate['tech_stack'] as $skill):?><span class="skill-chip<?= !$skill['active']?' inactive':'' ?>"><?= $e($skill['name']) ?></span><?php endforeach;?></span><?php else:?><p class="muted-text">Tech stack not added yet</p><?php endif;?></div><span class="badge <?= $candidate['classification']==='Genuine'?'green':'danger-badge' ?>"><?= $e($candidate['classification']) ?></span></section>
<section class="card admin-resume-card"><div><span class="eyebrow">PRIVATE DOCUMENT</span><h2>Resume</h2><?php if($candidate['resume_original_filename']):?><?php $resumeKb=max(1,(int)ceil((int)$candidate['resume_file_size']/1024));?><p><strong><?= $e($candidate['resume_original_filename']) ?></strong><br><?= $candidate['resume_mime_type']==='application/pdf'?'PDF':'DOCX' ?> · <?= $e(number_format($resumeKb)) ?> KB</p><?php else:?><p>No resume added yet.</p><?php endif;?></div><?php if($candidate['resume_original_filename']):?><div class="resume-actions"><a class="button secondary" target="_blank" rel="noopener" href="<?= $e($url('profile/resume?id='.$candidate['id'])) ?>">View Resume</a><a class="button primary" href="<?= $e($url('profile/resume?id='.$candidate['id'].'&download=1')) ?>">Download Resume</a></div><?php else:?><span class="badge neutral">No resume</span><?php endif;?></section>

<section class="card lifecycle-card"><div><span class="eyebrow">ACCOUNT ACCESS</span><h2>Candidate status</h2><p><?= $isActive?'The candidate can sign in and request interviews. Deactivation preserves the profile, tech stack, scheduled interviews, reports, and audit trail.':'The candidate cannot sign in, use the candidate portal, or be selected for a new admin booking.' ?></p></div><div class="lifecycle-action"><?php if($isActive):?><?php $deactivateMessage=$hasUpcoming?$candidate['full_name'].' has '.count($upcoming).' upcoming interview'.(count($upcoming)===1?'':'s').'. Deactivating the account will prevent candidate access, but every scheduled interview and assignment will remain active.':$candidate['full_name'].' will no longer be able to log in or book interviews. Existing interview history and reports will remain unchanged.';?><form method="post" action="<?= $e($url('admin/candidate/deactivate')) ?>" data-confirm-form data-confirm-title="Deactivate candidate?" data-confirm-message="<?= $e($deactivateMessage) ?>" data-confirm-button="Deactivate candidate"><?= Ui::csrf() ?><input type="hidden" name="candidate_id" value="<?= $e($candidate['id']) ?>"><button class="button secondary" type="submit">Deactivate candidate</button></form><?php else:?><form method="post" action="<?= $e($url('admin/candidate/reactivate')) ?>"><?= Ui::csrf() ?><input type="hidden" name="candidate_id" value="<?= $e($candidate['id']) ?>"><button class="button primary" type="submit">Reactivate candidate</button></form><?php endif;?></div></section>
<?php if($isActive&&$hasUpcoming):?><section class="upcoming-block card"><div><strong><?= $e($candidate['full_name']) ?> has <?= count($upcoming) ?> upcoming interview<?= count($upcoming)===1?'':'s' ?>.</strong><p>Deactivation leaves these bookings, resources, and support assignments active.</p></div><div class="upcoming-block-list"><?php foreach($upcoming as $i):?><a href="<?= $e($url('admin/interview?id='.$i['id'])) ?>"><span><?= $e($i['company_name']) ?></span><small><?= $e($i['display_time']) ?></small><?= Ui::icon('chevron') ?></a><?php endforeach;?></div></section><?php endif;?>

<?php foreach([['Upcoming',$upcoming],['Past',$past],['Cancelled',$cancelled]] as [$heading,$items]):?><section class="history-section"><div class="card-heading"><h2><?= $e($heading) ?></h2><span class="badge neutral"><?= count($items) ?></span></div><?php if(!$items):?><p class="muted-text">No <?= strtolower($heading) ?> interviews.</p><?php else:?><div class="interview-list"><?php foreach($items as $i):?><a class="interview-list-card <?= $i['status']==='CANCELLED'?'cancelled':'' ?>" href="<?= $e($url('admin/interview?id='.$i['id'])) ?>"><span class="date-tile"><strong><?= $e($i['start_local']->format('d')) ?></strong><?= $e(strtoupper($i['start_local']->format('M'))) ?></span><div class="interview-list-copy"><h2><?= $e($i['company_name']) ?></h2><p><?= $e($i['display_time']) ?> · <?= $e($i['resource_name']) ?></p></div><?= Ui::icon('chevron') ?></a><?php endforeach;?></div><?php endif;?></section><?php endforeach;?>

<section class="danger-zone card"><div><span class="eyebrow">DANGER ZONE</span><h2>Permanently delete candidate</h2><p>This removes the candidate account, profile, Tech Stack, login access, private photo, and resume. <?= $historyCount ?> existing interview<?= $historyCount===1?'':'s' ?> and all operational history will be preserved.</p></div><button class="button danger" type="button" data-delete-candidate>Permanently delete</button></section>
<dialog id="candidate-delete-dialog" class="modal delete-modal" aria-labelledby="candidate-delete-title"><form method="post" action="<?= $e($url('admin/candidate/delete')) ?>" data-delete-form data-confirm-value="DELETE"><?= Ui::csrf() ?><input type="hidden" name="candidate_id" value="<?= $e($candidate['id']) ?>"><div class="modal-icon danger-icon"><?= Ui::icon('shield') ?></div><h2 id="candidate-delete-title">Permanently delete candidate?</h2><p>This will remove <?= $e($candidate['full_name']) ?>’s account, profile, Tech Stack, login access, private photo, and resume. Existing interview and operational history will be preserved.</p><div class="field"><label for="confirmation_name">Type <strong>DELETE</strong> to confirm</label><input id="confirmation_name" name="confirmation_name" autocomplete="off" required></div><div class="modal-actions"><button class="button secondary" type="button" data-delete-cancel>Cancel</button><button class="button danger" type="submit" data-delete-submit disabled>Permanently delete</button></div></form></dialog>
